import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import fightBg from "../assets/IMAGES/FIGHT.png";
import { socket } from "../services/socket.js";
import EnterName from "./JoinorEnter.js";
function StartMatch() {
  const navigate = useNavigate();
  const [showEnterName, setShowEnterName] = useState(false);
  const [roomCodes, setRoomCodes] = useState("");
  const [join, setJoined] = useState(false);
  return (
    <>
      <div
        className="w-full h-screen bg-cover bg-center flex items-center justify-center"
        style={{ backgroundImage: `url(${fightBg})` }}
      >
      </div>  
      <div className="absolute top-[100px] left-[200px]">
          <button
            className=" px-8 py-4 bg-black text-white rounded-xl text-lg font-bold hover:bg-orange-500 hover:scale-105 transition "
            onClick={() => {
              setShowEnterName(true);
              setJoined(false);
            }}
          >
            Create Game
          </button>

          <button
            className=" px-8 py-4 bg-black text-white rounded-xl text-lg font-bold hover:bg-orange-500 hover:scale-105 transition "
            onClick={() => {
              setShowEnterName(true);
              setJoined(true);
            }}
          >
            Join Game
          </button>
        </div>
      

      {showEnterName && (
        <EnterName
          onClose={() => setShowEnterName(false)}
          roomCode={roomCodes}
          setRoomCode={setRoomCodes}
          Join={join}
        />
      )}
    </>
  );
}

export default StartMatch;
